// Golden replay of every tool state machine against Fixtures/tools/tools.json.
//
// Each scenario is generated by tools/fixtures/tools/gen_tools.js from the reference JS:
// crease-pattern setup, then a sequence of operations with the reference expectations recorded
// after each one (transition result, picked points/lines, resulting crease-pattern lines, and
// the by-value context mutations). This is the Swift <-> JS equivalence proof for the port.
import Foundation
import ORIPACore

enum ToolsScenarioTests {
    static var all: [TestSuite] {
        [
            TestSuite("CoreToolsScenarios") { harness in
                let fixture = try Fixtures.decode(ToolsFixture.self, "Fixtures/tools/tools.json")
                harness.expect(!fixture.scenarios.isEmpty, "tools fixture has scenarios")
                for scenario in fixture.scenarios {
                    run(harness, scenario)
                }
            },
        ]
    }

    // MARK: - Scenario driver

    private static func run(_ harness: TestHarness, _ scenario: ToolsFixture.Scenario) {
        let cp = CreasePattern()
        if scenario.setup.defaultSquare {
            cp.initializeDefaultSquare()
        }
        for line in scenario.setup.lines {
            let type = LineType(rawValue: Int(line[4])) ?? .undefined
            _ = cp.addLineCheckNoException(
                OriPoint(line[0], line[1]), OriPoint(line[2], line[3]), type
            )
        }

        if scenario.manager {
            runManager(harness, scenario, cp)
        } else {
            let stateMachine = ToolsTestSupport.makeMachine(
                scenario.machine, scenario.directSelection
            )
            if let initial = scenario.initial {
                harness.expectEqual(
                    stateMachine.getToolType(), initial.toolType,
                    "\(scenario.name): initial toolType"
                )
                harness.expectEqual(
                    stateMachine.getDirectSelectionEnabled(), initial.directSelectionEnabled,
                    "\(scenario.name): initial directSelectionEnabled"
                )
                harness.expectEqual(
                    stateMachine.hasBatchLineOperation(), initial.hasBatchLineOperation,
                    "\(scenario.name): initial hasBatchLineOperation"
                )
                harness.expectEqual(
                    stateMachine.hasBatchPointOperation(), initial.hasBatchPointOperation,
                    "\(scenario.name): initial hasBatchPointOperation"
                )
            }
            for (index, op) in scenario.ops.enumerated() {
                apply(
                    harness,
                    stateMachine,
                    cp,
                    op,
                    "\(scenario.name)#\(index)[\(op.op)]"
                )
            }
        }
        ToolsTestSupport.assertCP(harness, cp, scenario.final, "\(scenario.name): final")
    }

    private static func assertStateAndCP(
        _ harness: TestHarness,
        _ expect: ToolsFixture.Expect,
        _ label: String,
        state: CpState,
        cp: CreasePattern
    ) {
        if let expectedState = expect.state {
            ToolsTestSupport.assertState(harness, state, expectedState, label)
        }
        if let expectedCP = expect.cp {
            ToolsTestSupport.assertCP(harness, cp, expectedCP, label)
        }
    }

    // MARK: - Tool machine ops

    private static func apply(
        _ harness: TestHarness,
        _ stateMachine: CpStateMachine,
        _ cp: CreasePattern,
        _ op: ToolsFixture.Op,
        _ label: String
    ) {
        switch op.op {
        case "transition":
            guard let point = op.point, let expectedResult = op.expect.result else {
                harness.fail("\(label): malformed transition op")
                return
            }
            let result = stateMachine.doTransition(
                creasePattern: cp,
                snap: op.z ?? true,
                pointDouble: ToolsTestSupport.point(point),
                radius: op.radius ?? 5.0
            )
            harness.expectEqual(result, expectedResult, "\(label): transition result")
            assertStateAndCP(
                harness, op.expect, label, state: stateMachine.getState(), cp: cp
            )
        case "longTransition":
            guard let point = op.point, let expectedResult = op.expect.result else {
                harness.fail("\(label): malformed longTransition op")
                return
            }
            let result = stateMachine.doLongTransition(
                creasePattern: cp,
                z: op.z ?? true,
                pointDouble: ToolsTestSupport.point(point),
                radius: op.radius ?? 5.0
            )
            harness.expectEqual(result, expectedResult, "\(label): longTransition result")
            assertStateAndCP(
                harness, op.expect, label, state: stateMachine.getState(), cp: cp
            )
        case "batchPoint":
            guard let start = op.start, let end = op.end else {
                harness.fail("\(label): malformed batchPoint op")
                return
            }
            let context = ToolsTestSupport.makeContext(op.context)
            let group = stateMachine.doBatchPointOperation(
                context: context,
                cp: cp,
                start: ToolsTestSupport.oriPoint(start),
                end: ToolsTestSupport.oriPoint(end)
            )
            if let expectedGroup = op.expect.group {
                ToolsTestSupport.assertGroup(harness, group, expectedGroup, label)
            }
            assertStateAndCP(
                harness, op.expect, label, state: stateMachine.getState(), cp: cp
            )
        case "batchLine":
            guard let start = op.start, let end = op.end else {
                harness.fail("\(label): malformed batchLine op")
                return
            }
            let context = ToolsTestSupport.makeContext(op.context)
            let group = stateMachine.doBatchLineOperation(
                context: context,
                cp: cp,
                start: ToolsTestSupport.oriPoint(start),
                end: ToolsTestSupport.oriPoint(end)
            )
            if let expectedGroup = op.expect.group {
                ToolsTestSupport.assertGroup(harness, group, expectedGroup, label)
            }
            assertStateAndCP(
                harness, op.expect, label, state: stateMachine.getState(), cp: cp
            )
        case "finish":
            let context = ToolsTestSupport.makeContext(op.context)
            let group = stateMachine.finish(context: context, cp: cp)
            if let expectedGroup = op.expect.group {
                ToolsTestSupport.assertGroup(harness, group, expectedGroup, label)
            }
            if let expectedContext = op.expect.context {
                if let context {
                    harness.expectClose(
                        context.angle, expectedContext.angle, accuracy: ToolsTestSupport.accuracy,
                        "\(label): context angle"
                    )
                    harness.expectClose(
                        context.length,
                        expectedContext.length,
                        accuracy: ToolsTestSupport.accuracy,
                        "\(label): context length"
                    )
                } else {
                    harness.fail("\(label): expected context mutation but context is nil")
                }
            } else {
                harness.expectNil(context, "\(label): unexpected context")
            }
            assertStateAndCP(
                harness, op.expect, label, state: stateMachine.getState(), cp: cp
            )
        case "selectAll":
            guard let selectLineSM = stateMachine as? SelectLineSM else {
                harness.fail("\(label): selectAll on non-SelectLineSM")
                return
            }
            selectLineSM.selectAll(cp)
            if let expectedState = op.expect.state {
                ToolsTestSupport.assertState(
                    harness, stateMachine.getState(), expectedState, label
                )
            }
        case "deselectAll":
            guard let selectLineSM = stateMachine as? SelectLineSM else {
                harness.fail("\(label): deselectAll on non-SelectLineSM")
                return
            }
            selectLineSM.deselectAll()
            if let expectedState = op.expect.state {
                ToolsTestSupport.assertState(
                    harness, stateMachine.getState(), expectedState, label
                )
            }
        case "deleteSelected":
            guard let selectLineSM = stateMachine as? SelectLineSM else {
                harness.fail("\(label): deleteSelected on non-SelectLineSM")
                return
            }
            let group = selectLineSM.deleteSelected(cp)
            if let expectedGroup = op.expect.group {
                ToolsTestSupport.assertGroup(harness, group, expectedGroup, label)
            }
            assertStateAndCP(
                harness, op.expect, label, state: stateMachine.getState(), cp: cp
            )
        case "getNew":
            let fresh = stateMachine.getNew()
            harness.expect(fresh !== stateMachine, "\(label): getNew returns a new machine")
            ToolsTestSupport.assertFlags(
                harness,
                op.expect,
                label,
                toolType: { fresh.getToolType() },
                directSelectionEnabled: { fresh.getDirectSelectionEnabled() },
                hasBatchLineOperation: { fresh.hasBatchLineOperation() },
                hasBatchPointOperation: { fresh.hasBatchPointOperation() }
            )
        case "toolType":
            harness.expectEqual(
                stateMachine.getToolType(), op.expect.toolType ?? Int.min,
                "\(label): toolType"
            )
        default:
            harness.fail("\(label): unknown machine op \(op.op)")
        }
    }

    // MARK: - StateMachineManager ops

    private static func runManager(
        _ harness: TestHarness,
        _ scenario: ToolsFixture.Scenario,
        _ cp: CreasePattern
    ) {
        let manager = StateMachineManager()
        for (index, op) in scenario.ops.enumerated() {
            let label = "\(scenario.name)#\(index)[\(op.op)]"
            switch op.op {
            case "newMachine":
                guard let machineName = op.machine else {
                    harness.fail("\(label): malformed newMachine op")
                    return
                }
                manager.newMachine(
                    ToolsTestSupport.makeMachine(machineName, op.directSelection ?? false)
                )
                assertManagerFlags(harness, manager, op.expect, label)
            case "resetMachine":
                manager.resetMachine()
                assertManagerFlags(harness, manager, op.expect, label)
            case "transition":
                guard let point = op.point, let expectedResult = op.expect.result else {
                    harness.fail("\(label): malformed transition op")
                    return
                }
                let result = manager.doTransition(
                    creasePattern: cp,
                    snap: op.z ?? true,
                    pointDouble: ToolsTestSupport.point(point),
                    radius: op.radius ?? 5.0
                )
                harness.expectEqual(result, expectedResult, "\(label): transition result")
                assertManagerStateAndCP(harness, manager, cp, op.expect, label)
            case "longTransition":
                guard let point = op.point, let expectedResult = op.expect.result else {
                    harness.fail("\(label): malformed longTransition op")
                    return
                }
                let result = manager.doLongTransition(
                    creasePattern: cp,
                    z: op.z ?? true,
                    pointDouble: ToolsTestSupport.point(point),
                    radius: op.radius ?? 5.0
                )
                harness.expectEqual(result, expectedResult, "\(label): longTransition result")
                assertManagerStateAndCP(harness, manager, cp, op.expect, label)
            case "batchLine":
                guard let start = op.start, let end = op.end else {
                    harness.fail("\(label): malformed batchLine op")
                    return
                }
                let group = manager.doBatchLineOperation(
                    context: ToolsTestSupport.makeContext(op.context),
                    cp: cp,
                    start: ToolsTestSupport.oriPoint(start),
                    end: ToolsTestSupport.oriPoint(end)
                )
                if let expectedGroup = op.expect.group {
                    ToolsTestSupport.assertGroup(harness, group, expectedGroup, label)
                }
                assertManagerStateAndCP(harness, manager, cp, op.expect, label)
            case "batchPoint":
                guard let start = op.start, let end = op.end else {
                    harness.fail("\(label): malformed batchPoint op")
                    return
                }
                let group = manager.doBatchPointOperation(
                    context: ToolsTestSupport.makeContext(op.context),
                    cp: cp,
                    start: ToolsTestSupport.oriPoint(start),
                    end: ToolsTestSupport.oriPoint(end)
                )
                if let expectedGroup = op.expect.group {
                    ToolsTestSupport.assertGroup(harness, group, expectedGroup, label)
                }
                assertManagerStateAndCP(harness, manager, cp, op.expect, label)
            case "finish":
                let group = manager.finish(
                    context: ToolsTestSupport.makeContext(op.context), cp: cp
                )
                if let expectedGroup = op.expect.group {
                    ToolsTestSupport.assertGroup(harness, group, expectedGroup, label)
                }
                assertManagerStateAndCP(harness, manager, cp, op.expect, label)
            case "toolType":
                harness.expectEqual(
                    manager.getToolType(), op.expect.toolType ?? Int.min,
                    "\(label): toolType"
                )
            default:
                harness.fail("\(label): unknown manager op \(op.op)")
            }
        }
    }

    private static func assertManagerFlags(
        _ harness: TestHarness,
        _ manager: StateMachineManager,
        _ expect: ToolsFixture.Expect,
        _ label: String
    ) {
        ToolsTestSupport.assertFlags(
            harness,
            expect,
            label,
            toolType: { manager.getToolType() },
            directSelectionEnabled: { manager.getDirectSelectionEnabled() },
            hasBatchLineOperation: { manager.hasBatchLineOperation() },
            hasBatchPointOperation: { manager.hasBatchPointOperation() }
        )
    }

    private static func assertManagerStateAndCP(
        _ harness: TestHarness,
        _ manager: StateMachineManager,
        _ cp: CreasePattern,
        _ expect: ToolsFixture.Expect,
        _ label: String
    ) {
        if let expectedState = expect.state {
            ToolsTestSupport.assertState(harness, manager.getState(), expectedState, label)
        }
        if let expectedCP = expect.cp {
            ToolsTestSupport.assertCP(harness, cp, expectedCP, label)
        }
    }
}
